import { useRole } from "../../context/RoleContext";
import { useNavigate, useLocation } from "react-router-dom";

const navLinks = {
  recruiter: [
    { path: "/job-setup",  label: "New Search" },
    { path: "/results/1",  label: "Results" },
    { path: "/shortlist/1",label: "Shortlist" },
  ],
  hiring_manager: [
    { path: "/hm-dashboard", label: "Dashboard" },
    { path: "/hm-review/1",  label: "Review" },
  ],
};

export default function Layout({ children }) {
  const { role, setRole } = useRole();
  const navigate = useNavigate();
  const location = useLocation();

  return (
    <div style={{ minHeight: "100vh", background: "var(--navy)" }}>
      {/* Top nav */}
      <nav style={{
        background: "rgba(10,15,30,0.8)",
        backdropFilter: "blur(12px)",
        borderBottom: "1px solid var(--border)",
        padding: "0 32px",
        height: "64px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        position: "sticky",
        top: 0,
        zIndex: 100,
      }}>
        {/* Logo */}
        <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
          <div style={{
            width: 32, height: 32, borderRadius: 8,
            background: "var(--blue)",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 16, fontWeight: 800, fontFamily: "Plus Jakarta Sans",
          }}>P</div>
          <span style={{
            fontFamily: "Plus Jakarta Sans", fontWeight: 700,
            fontSize: 16, color: "var(--text-primary)"
          }}>PassiveTalent</span>
        </div>

        {/* Role badge + switch */}
        <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
          <span className="badge badge-blue">
            {role === "recruiter" ? "Recruiter" : "Hiring Manager"}
          </span>
          <button className="btn-secondary" style={{ padding: "8px 16px", fontSize: 13 }}
            onClick={() => { setRole(null); navigate("/"); }}>
            Switch Role
          </button>
        </div>
      </nav>

      {/* Page content */}
      <main style={{ maxWidth: 1200, margin: "0 auto", padding: "40px 32px" }}>
        {children}
      </main>
    </div>
  );
}
